import*as T from'three';
const keys=['left','right','top','bottom','near','far','zoom'],ease=t=>t*t*(3-2*t);
export function captureCamera(camera){camera.updateMatrixWorld(true);return{position:camera.getWorldPosition(new T.Vector3()),quaternion:camera.getWorldQuaternion(new T.Quaternion()),...Object.fromEntries(keys.map(k=>[k,camera[k]]))};}
export function createCameraHandoff(from,to,{reduced=false,initialCover=0}={}){const angle=from.quaternion.angleTo(to.quaternion),a=(from.right-from.left)/from.zoom,b=(to.right-to.left)/to.zoom,scale=Math.max(a/b,b/a),pan=from.position.distanceTo(to.position)/Math.max(.1,Math.min(a,b)),covered=reduced||initialCover>0||angle>Math.PI/3||scale>2.2||pan>1.2,duration=covered?1.25:Math.max(.8,1.5*angle/.45,1.5*(Math.abs(a-b)/Math.min(a,b))/.7);return{from,to,angle,covered,duration,initialCover:Math.max(0,Math.min(1,initialCover))};}
export function applyCameraHandoff(camera,plan,elapsed){const t=Math.max(0,Math.min(1,elapsed/plan.duration)),s=ease(t),{from,to}=plan;let cover=0;if(plan.covered){const frame=t<.5?from:to;camera.position.copy(frame.position);camera.quaternion.copy(frame.quaternion);for(const k of keys)camera[k]=frame[k];cover=t<.4?plan.initialCover+(1-plan.initialCover)*ease(t/.4):t>.6?1-ease((t-.6)/.4):1;}else{camera.position.lerpVectors(from.position,to.position,s);camera.quaternion.slerpQuaternions(from.quaternion,to.quaternion,s);for(const k of keys)camera[k]=from[k]+(to[k]-from[k])*s;}camera.updateProjectionMatrix();camera.updateMatrixWorld(true);return{cover,complete:t===1,covered:plan.covered,duration:plan.duration};}
